public class TestArchDetection2 {
    public static void main(String[] args) {
        // Test various os.arch values
        String[] testArchs = {
            "amd64",      // 64-bit JVM on Windows/Linux
            "x86_64",     // 64-bit JVM on macOS
            "ia64",       // Itanium 64-bit
            "aarch64",    // ARM 64-bit
            "x86",        // 32-bit JVM
            "i386",       // 32-bit JVM
            "arm",        // 32-bit ARM
            "arm64",      // ARM 64-bit (iOS)
            "ppc64",      // PowerPC 64-bit
            "sparcv9",    // SPARC 64-bit - problematic!
            "AMD64",      // Uppercase variant
        };

        System.out.println("Testing various os.arch values:");
        System.out.println("================================");

        for (String osArch : testArchs) {
            // Old check (buggy)
            boolean x64Old = osArch.contains("64");

            // New check (fixed)
            boolean x64New = "64".equals(System.getProperty("sun.arch.data.model")) 
                || osArch.contains("64") 
                || osArch.contains("86_64");

            String status = (x64Old == x64New) ? "OK" : "DIFFER";
            if (x64Old != x64New) {
                status = "FIXED!";
            }

            String libName = x64New ? "jemalloc" : "jemalloc32";

            System.out.printf("%-12s  old=%-5s  new=%-5s  %s  -> %s.dll%n", 
                osArch, x64Old, x64New, status, libName);
        }

        System.out.println("\nNote: sun.arch.data.model would override os.arch in real JVM");
    }
}
