import java.util.HashMap;
import java.util.Map;

public class TestFix {

    // Simulate the old buggy check
    private static boolean is64BitOld(String osArch) {
        return osArch.contains("64");
    }

    // Simulate the new fixed check (without sun.arch.data.model override)
    private static boolean is64BitNew(String osArch, String dataModel) {
        return "64".equals(dataModel) || osArch.contains("64") || osArch.contains("86_64");
    }

    public static void main(String[] args) {
        System.out.println("Testing the 64-bit detection fix:");
        System.out.println("===================================\n");

        // Test cases: osArch -> expected 64-bit?
        Map<String, Boolean> testCases = new HashMap<>();
        testCases.put("amd64", true);      // 64-bit JVM on Windows/Linux
